import { Hono } from './hono'

describe('set-cookie merge regression (temp)', () => {
  it('keeps middleware and handler cookies (scenario B)', async () => {
    const app = new Hono()
    app.use(async (c, next) => {
      c.res.headers.set('X-Something', 'true')
      c.header('Set-Cookie', 'mw_cookie=hello; Path=/', { append: true })
      await next()
    })
    app.get('/test', () => {
      const res = new Response('ok')
      res.headers.append('set-cookie', 'handler_cookie=world; Path=/; HttpOnly')
      return res
    })
    const res = await app.request('/test')
    expect(res.headers.getSetCookie()).toEqual([
      'mw_cookie=hello; Path=/',
      'handler_cookie=world; Path=/; HttpOnly',
    ])
    expect(res.headers.get('X-Something')).toBe('true')
  })

  it('keeps prepared middleware cookies and handler cookies (scenario A)', async () => {
    const app = new Hono()
    app.use(async (c, next) => {
      c.header('Set-Cookie', 'mw_cookie=hello; Path=/', { append: true })
      await next()
    })
    app.get('/test', () => {
      const res = new Response('ok')
      res.headers.append('set-cookie', 'handler_cookie=world; Path=/; HttpOnly')
      return res
    })
    const res = await app.request('/test')
    expect(res.headers.getSetCookie()).toEqual([
      'mw_cookie=hello; Path=/',
      'handler_cookie=world; Path=/; HttpOnly',
    ])
  })
})
EOF
